-- RLS, RBAC, data-scope, compartment and append-only audit controls
create or replace function public.has_permission(permission_code text) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.user_roles ur join public.role_permissions rp on rp.role_id=ur.role_id join public.permissions p on p.id=rp.permission_id where ur.user_id=auth.uid() and p.code=permission_code); $$;
create or replace function public.has_compartment(classification_code text) returns boolean language sql stable security definer set search_path='' as $$ select classification_code in ('PUBLIC','INTERNAL') or exists(select 1 from public.user_compartments uc join public.security_compartments sc on sc.id=uc.compartment_id where uc.user_id=auth.uid() and sc.code::text=classification_code); $$;
create or replace function public.has_scope(scope_code text) returns boolean language sql stable security definer set search_path='' as $$ select scope_code is null or exists(select 1 from public.data_scopes ds where ds.user_id=auth.uid() and ds.active and (ds.scope_code=scope_code or ds.scope_code='*')); $$;
create or replace function public.can_access_case(target_case_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select target_case_id is null or exists(select 1 from public.cases c where c.id=target_case_id and (c.responsible_officer_id=auth.uid() or exists(select 1 from public.case_assignments ca where ca.case_ref=c.id and ca.user_id=auth.uid() and ca.ended_at is null))); $$;
create or replace function public.record_access_allowed(classification_code text, scope_code text, target_case_id uuid) returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and public.has_compartment(classification_code) and public.has_scope(scope_code) and (target_case_id is null or public.can_access_case(target_case_id)); $$;
create or replace function public.prevent_audit_mutation() returns trigger language plpgsql security definer set search_path='' as $$ begin raise exception 'audit_events is append-only'; end; $$;
create trigger audit_events_append_only before update or delete on public.audit_events for each row execute function public.prevent_audit_mutation();
