do $policy$ declare item record; begin for item in select * from jsonb_each_text('{"roles":"admin.manage_roles","permissions":"admin.manage_roles","user_roles":"admin.manage_roles","role_permissions":"admin.manage_roles","data_scopes":"admin.manage_users","security_compartments":"admin.manage_roles","user_compartments":"admin.manage_roles","divisions":"admin.manage_users","units":"admin.manage_users","teams":"admin.manage_users","positions":"admin.manage_users","officer_assignments":"admin.manage_users","people":"admin.manage_users","leaders":"leadership.view_restricted","leader_positions":"leadership.view_restricted","government_bodies":"oversight.view","government_body_contacts":"oversight.view","liaison_officers":"oversight.view","complaints":"complaints.view","complaint_parties":"complaints.view","complaint_documents":"complaints.view","screening_assessments":"complaints.screen","screening_decisions":"complaints.screen","cases":"investigations.view","case_assignments":"investigations.view","case_parties":"investigations.view","case_events":"investigations.view","case_tasks":"investigations.view","case_extensions":"investigations.view","allegations":"investigations.view","investigations":"investigations.view","investigation_plans":"investigations.view","investigation_plan_steps":"investigations.view","evidence_items":"evidence.manage","evidence_custody_events":"evidence.manage","interviews":"investigations.view","interview_participants":"investigations.view","statutory_notices":"investigations.view","information_requests":"investigations.view","responses":"investigations.view","findings":"investigations.view","right_to_be_heard_notices":"investigations.view","right_to_be_heard_responses":"investigations.view","closure_decisions":"investigations.view","annual_statements":"annual_statements.view_secret","annual_statement_periods":"annual_statements.view_secret","annual_statement_reminders":"annual_statements.view_secret","annual_statement_breach_notices":"annual_statements.view_secret","assets":"annual_statements.view_secret","liabilities":"annual_statements.view_secret","income_sources":"annual_statements.view_secret","business_interests":"annual_statements.view_secret","directorships":"annual_statements.view_secret","shareholdings":"annual_statements.view_secret","gifts":"annual_statements.view_secret","financial_transactions":"annual_statements.view_secret","declaration_variances":"annual_statements.view_secret","explanation_requests":"annual_statements.view_secret","explanation_responses":"annual_statements.view_secret","recommendations":"compliance.view","recommendation_recipients":"compliance.view","agency_responses":"compliance.view","compliance_actions":"compliance.view","compliance_evidence":"compliance.view","compliance_reviews":"compliance.view","escalations":"compliance.view","moc_meetings":"commission.view","moc_agenda_items":"commission.view","moc_submissions":"commission.view","moc_decisions":"commission.view","moc_actions":"commission.view","delegations":"commission.view","legal_matters":"legal.view_privileged","constitutional_references":"legal.view_privileged","litigation_events":"legal.view_privileged","legislative_reviews":"legal.view_privileged","public_prosecutor_referrals":"legal.view_privileged","tribunal_matters":"legal.view_privileged","monitoring_programs":"oversight.view","monitoring_activities":"oversight.view","inspections":"oversight.view","inspection_findings":"oversight.view","service_delivery_indicators":"oversight.view","systemic_issues":"oversight.view","intelligence_reports":"intelligence.view_secret","intelligence_sources":"intelligence.view_secret","intelligence_entities":"intelligence.view_secret","intelligence_links":"intelligence.view_secret","documents":"reports.view","document_versions":"reports.view","export_events":"reports.view","notifications":"notifications.view","workflow_tasks":"tasks.view","audit_events":"audit.view","system_settings":"admin.manage_settings"}'::jsonb) loop e